function localizeRenderedUi() {
  if (getLanguage() === "ru") return;
  const root = document.body;
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => {
    let value = node.nodeValue;
    for (const [source, target] of [...uiEnglish].sort((a, b) => b[0].length - a[0].length)) value = value.split(source).join(target);
    node.nodeValue = value;
  });
  document.querySelectorAll("input, textarea, button").forEach((element) => {
    for (const attribute of ["placeholder", "aria-label", "title"]) {
      let value = element.getAttribute(attribute);
      if (!value) continue;
      for (const [source, target] of [...uiEnglish].sort((a, b) => b[0].length - a[0].length)) value = value.split(source).join(target);
      element.setAttribute(attribute, value);
    }
  });
}
const uiObserver = new MutationObserver(() => localizeRenderedUi());
uiObserver.observe(document.body, { childList: true, subtree: true });
