function wireCanvas() {
  const wrap = document.querySelector("#canvas-wrap"), canvas = document.querySelector("#knowledge-canvas");
  let scale = 1, dragging = false, pointerId = null, startX = 0, startY = 0, originX = 0, originY = 0, frame = 0;
  const paint = () => { frame = 0; canvas.style.transform = `translate3d(${originX}px,${originY}px,0) scale(${scale})`; const zoom = document.querySelector("#map-zoom"); if (zoom) zoom.textContent = `${Math.round(scale * 100)}%`; };
  const schedulePaint = () => { if (!frame) frame = requestAnimationFrame(paint); };
  wrap.onpointerdown = (event) => { if (event.target.closest(".map-node")) return; dragging = true; pointerId = event.pointerId; startX = event.clientX - originX; startY = event.clientY - originY; wrap.setPointerCapture(pointerId); wrap.classList.add("dragging"); };
  wrap.onpointermove = (event) => { if (!dragging || event.pointerId !== pointerId) return; originX = event.clientX - startX; originY = event.clientY - startY; schedulePaint(); };
  const stopDragging = () => { dragging = false; pointerId = null; wrap.classList.remove("dragging"); };
  wrap.onpointerup = stopDragging; wrap.onpointercancel = stopDragging; wrap.onpointerleave = (event) => { if (dragging && event.buttons === 0) stopDragging(); };
  wrap.onwheel = (event) => { event.preventDefault(); scale = Math.max(.6, Math.min(1.6, scale + (event.deltaY < 0 ? .08 : -.08))); schedulePaint(); };
  document.querySelector("#zoom-in").onclick = () => { scale = Math.min(1.6, scale + .1); schedulePaint(); };
  document.querySelector("#zoom-out").onclick = () => { scale = Math.max(.6, scale - .1); schedulePaint(); };
  document.querySelector("#map-focus").onclick = () => { originX = (wrap.clientWidth - canvas.offsetWidth * scale) / 2; originY = (wrap.clientHeight - canvas.offsetHeight * scale) / 2; schedulePaint(); };
  document.querySelector("#map-reset").onclick = () => { scale = 1; originX = 0; originY = 0; schedulePaint(); };
}
