function renderCurrentScreen() {
  if (currentScreen === "settings") return renderThemeSettings();
  if (currentScreen === "sessions") return renderSessions();
  if (currentScreen === "import") return renderImport();
  if (currentScreen === "copilot") return renderCopilot();
  if (currentScreen === "compile") return renderCompile();
  if (currentScreen === "timeline") return renderMap();
  if (currentScreen === "session" && currentSessionId) return showSession(currentSessionId);
  return renderOverview();
}
